window.loanAgreementTemplate = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Maluti Fruit Loan / Advance Agreement</title><style>\n*{box-sizing:border-box}body{margin:0;background:#eee;font-family:Arial,sans-serif;color:#171717;font-size:10pt;line-height:1.35}main{max-width:210mm;margin:24px auto;padding:16mm;background:white}p{margin:5pt 0;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;margin:9pt 0;break-inside:avoid}td{border:1px solid #aaa;padding:4pt 6pt;vertical-align:middle}td p{margin:0}td:first-child{width:40%}.logo{width:170px;max-width:40%;height:auto;display:block;margin-bottom:12px}footer{font-size:8pt;color:#555;margin-top:22px}@page{size:A4;margin:14mm}@media print{body{background:white}main{padding:0;margin:0;max-width:none}}@media(max-width:600px){main{margin:0;padding:20px}td{overflow-wrap:anywhere}span{font-size:inherit!important}}\n</style></head><body><main><img class=\"logo\" alt=\"Maluti Fruit\" src=\"data:image/jpeg;base64,\"><p style=\"text-align:center\">\u00a0</p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:21.0pt\">MALUTI FRUIT</span></p><p style=\"text-align:center\"><span style=\"font-weight:bold;font-size:13.0pt\">LOAN / ADVANCE AGREEMENT</span></p><p style=\"text-align:center\">\u00a0</p><table><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Application No.</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{application_no}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Application Date</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{application_date}}</p></td></tr></table><p style=\"text-align:left\">\u00a0</p><table><tr><td colspan=\"3\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">1. EMPLOYEE DETAILS</span></p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Employee Number</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{employee_number}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Full Name &amp; Surname</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{employee_name}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Identity / Passport No.</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{employee_id}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Department / Position</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{department}}</p></td></tr></table><p style=\"text-align:left\">\u00a0</p><table><tr><td colspan=\"2\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">2. LOAN / ADVANCE DETAILS</span></p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Loan Type</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{loan_type}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Amount Requested</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{amount_requested}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Amount Approved</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{amount_approved}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Monthly Deduction</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{monthly_deduction}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">First Deduction Month</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{first_deduction_date}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Interest Rate</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{annual_interest_rate}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Number of Instalments</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{number_of_instalments}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Final Instalment (if different)</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{final_instalment}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Reason for Loan / Advance</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{loan_reason}}</p></td></tr></table><p style=\"text-align:left\">\u00a0</p><p style=\"text-align:left\"><span style=\"\">Interest and fees: This loan/advance is interest-</span><span style=\"\">free</span><span style=\"\"> and no administration fee will be charged, unless otherwise lawfully agreed in writing.</span></p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">3. APPLICATION DECISION</span></p></td></tr></table><p style=\"text-align:left\"><span style=\"\">If approved, Maluti Fruit agrees to advance the approved amount to the employee, subject to this agreement. Approval is effective only once signed by the </span><span style=\"\">authorized</span><span style=\"\"> manager.</span></p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"\"></span><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">4. EMPLOYEE ACKNOWLEDGEMENT AND SALARY-DEDUCTION AUTHORISATION</span></p></td></tr></table><p style=\"text-align:left\">I, <strong>{{employee_name}}</strong> with identity/passport number <strong>{{employee_id}}</strong>, acknowledge that I have applied for and/or received a loan/advance from Maluti Fruit.</p><p style=\"text-align:left\"><span style=\"\">I acknowledge that the amount above is a debt owed by me to Maluti Fruit. I voluntarily and in writing </span><span style=\"\">authorize</span><span style=\"\"> Maluti Fruit to deduct the stated monthly amount from my remuneration, commencing on the date stated above and continuing monthly until the full outstanding balance has been repaid.</span></p><p style=\"text-align:left\"><span style=\"\">This </span><span style=\"\">authorization</span><span style=\"\"> relates specifically to the loan/advance recorded in this agreement. Maluti Fruit may not increase the deduction or change the repayment terms unless the change is recorded in writing and agreed where legally required.</span></p><p style=\"text-align:left\"><span style=\"\">I understand that lawful payroll deductions remain subject to applicable South African legislation and that this agreement does not </span><span style=\"\">authorize</span><span style=\"\"> any deduction prohibited by law.</span></p><p style=\"text-align:left\">\u00a0</p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">6. EARLY OR ADDITIONAL REPAYMENT</span></p></td></tr></table><p style=\"text-align:left\"><span style=\"\">The employee may repay all or part of the outstanding balance earlier than scheduled. Any additional or early payment will reduce the outstanding balance. Maluti Fruit will adjust or stop payroll deductions once the debt has been fully repaid.</span></p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">7. TERMINATION OF EMPLOYMENT</span></p></td></tr></table><p style=\"text-align:left\"><span style=\"\">If my employment with Maluti Fruit ends for any reason before this loan/advance is fully repaid, the outstanding balance will remain a debt owed by me to Maluti Fruit.</span></p><p style=\"text-align:left\"><span style=\"\">I </span><span style=\"\">authorize</span><span style=\"\"> Maluti Fruit, subject to applicable South African law, to deduct any amount that may lawfully be deducted from remuneration or other amounts payable to me when my employment ends.</span></p><p style=\"text-align:left\"><span style=\"\">If the full balance cannot lawfully be deducted from amounts payable to me, the remaining balance will remain payable. The parties may record a lawful repayment arrangement in writing. This clause does not </span><span style=\"\">authorize</span><span style=\"\"> a deduction prohibited by law.</span></p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">8. GENERAL TERMS</span></p></td></tr></table><p style=\"text-align:left\"><span style=\"\">The information supplied in this application is true and correct.</span></p><p style=\"text-align:left\"><span style=\"\">I understand the amount borrowed, the repayment period and the monthly deduction.</span></p><p style=\"text-align:left\"><span style=\"\">I give the salary-deduction </span><span style=\"\">authorization</span><span style=\"\"> voluntarily and in writing.</span></p><p style=\"text-align:left\"><span style=\"\">Maluti Fruit will keep a record of payments, deductions and the outstanding balance.</span></p><p style=\"text-align:left\"><span style=\"\">No further deduction relating to this loan/advance may be made after the debt has been paid in full.</span></p><p style=\"text-align:left\"><span style=\"\">Any amendment must be recorded in writing and agreed where legally required.</span></p><p style=\"text-align:left\"><span style=\"\">A delay or failure by Maluti Fruit to enforce a right does not waive that right.</span></p><p style=\"text-align:left\"><span style=\"\">If any term is invalid or unenforceable, the remaining terms will continue to apply.</span></p><p style=\"text-align:left\"><span style=\"\">This agreement is governed by applicable South African law.</span></p><table><tr><td colspan=\"1\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">9. EMPLOYEE DECLARATION AND SIGNATURES</span></p></td></tr></table><p style=\"text-align:left\"><span style=\"\">I confirm that I have read and understood this agreement, that I have had an opportunity to ask questions, and that I agree to its terms.</span></p><table><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Employee Name</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{employee_name}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Employee Signature</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">\u00a0</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Date</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{application_date}}</p></td></tr></table><p style=\"text-align:left\">\u00a0</p><table><tr><td colspan=\"2\" style=\"background:#666666;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:10.0pt;color:#FFFFFF\">10. OFFICE USE</span></p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Approved Amount</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{amount_approved}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Monthly Deduction</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{monthly_deduction}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">First Deduction</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{first_deduction_date}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Expected Final Deduction</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{expected_final_deduction}}</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Authorized</span><span style=\"font-weight:bold;font-size:8.5pt\"> By</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">\u00a0</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Signature</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">\u00a0</p></td></tr><tr><td colspan=\"1\" style=\"background:#F2F2F2;\"><p style=\"text-align:left\"><span style=\"font-weight:bold;font-size:8.5pt\">Date</span></p></td><td colspan=\"1\" style=\"\"><p style=\"text-align:left\">{{application_date}}</p></td></tr></table><p style=\"text-align:left\">\u00a0</p><p style=\"text-align:center\"><span style=\"font-style:italic;font-size:7.5pt;color:#666666\">Internal form note: Payroll should retain the signed agreement and update the repayment record after each deduction.</span></p><footer>Maluti Fruit | Loan / Advance Agreement | Confidential</footer></main></body></html>";
